# ==========================================
# INIMIGO 7: FIGHTER (Guarda da Porta)
# ==========================================
ENTITY fighter1
# Rotação 0.0 para olhar para frente
TRANSFORM 0.0 0.0 -450.0 PI
PHYSICS 0.0 0.0 0.0 0.90
# Hitbox Aumentada (1.6x maior que o Scout)
COLLISION -11.0 0.0 -11.0 11.0 38.0 11.0 0 0
HEALTH 150.0
RENDER 12 255 255 255 255
# AI: Visão 200, Ataque 150 (Mid Range)
AI_CONTROL 150.0 125.0

ENTITY fighter1_gun
TRANSFORM 0 0 0
# Weapon Range 400
WEAPON WEAPON_PULSE_LASER 0.3 250.0 5.0 400.0 2.0 2 0.1
ATTACHMENT fighter1 6.25 15.50 0.00
LINK_WEAPON fighter1 0 fighter1_gun 0 1


